var plotParam = Tama.Args.Get(args, "plotParam", "Mark");
var res = new List<object>();
foreach (var po in (object[])args["plots"]) {
  var pdict = (IDictionary<string,object>)po;
  int fid = Convert.ToInt32(pdict["floorId"]);
  var floor = doc.GetElement(new ElementId(fid)) as Floor;
  var sk = doc.GetElement(floor.SketchId) as Sketch;
  var plot = new List<Curve>(); foreach (CurveArray ca in sk.Profile) { foreach (Curve c in ca) plot.Add(c.CreateTransformed(Transform.CreateTranslation(new XYZ(0,0,-c.GetEndPoint(0).Z)))); break; }
  var edgeLens = plot.Select(c => Math.Round(c.Length*0.3048,2)).ToList();
  var lines = new List<string>();
  foreach (var o in (object[])pdict["ids"]) {
    var ce = doc.GetElement(new ElementId(Convert.ToInt32(o))) as CurveElement; var c = ce.GeometryCurve;
    var m = c.Evaluate(0.5,true); m = new XYZ(m.X, m.Y, 0);
    var best = plot.Select((p,i) => { var u = p.Clone(); u.MakeUnbound(); return new { i, d = u.Project(m).Distance }; }).OrderBy(x => x.d).First();
    lines.Add(ce.Id.IntegerValue + (c is Arc ? "(A)" : "(L)") + " len " + Math.Round(c.Length*0.3048,2) + " -> edge" + best.i + " @ " + Math.Round(best.d*0.3048,3));
  }
  res.Add(new { fid, plotId = floor.LookupParameter(plotParam)?.AsString(), type = floor.Name, edgeLens, lines });
}
return res;
